  #region Enums
  /// <summary>
  /// Match mode determines team size, player count, and map config.
  /// </summary>
  public enum MatchMode {
    [pbr::OriginalName("MATCH_MODE_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// 回合制 PVP 5v5(二期启用):FIFO 凑 10 人,前 5 后 5 各一队
    /// </summary>
    [pbr::OriginalName("MATCH_MODE_5V5")] _5V5 = 1,
    /// <summary>
    /// 6 players total(未开放)
    /// </summary>
    [pbr::OriginalName("MATCH_MODE_3V3")] _3V3 = 2,
    /// <summary>
    /// 2 players total(回合制 PVP,一期启用)
    /// </summary>
    [pbr::OriginalName("MATCH_MODE_1V1")] _1V1 = 3,
    /// <summary>
    /// 回合制 PVE 单人,即时开战(伪匹配)
    /// </summary>
    [pbr::OriginalName("MATCH_MODE_PVE_SOLO")] PveSolo = 4,
    /// <summary>
    /// 回合制 PVE 组队:按 JoinQueueRequest.team_size 的人数档 FIFO 凑满(1 人档即时开战)
    /// </summary>
    [pbr::OriginalName("MATCH_MODE_PVE_TEAM")] PveTeam = 5,
    /// <summary>
    /// 场景发起 PK(切磋):点名成局,不入队
    /// </summary>
    [pbr::OriginalName("MATCH_MODE_PVP_CHALLENGE")] PvpChallenge = 6,
    /// <summary>
    /// 真人人数档PVP：每侧1..5人，整支队伍保持同侧，等待真人对手（真实养成，正式计分）。
    /// </summary>
    [pbr::OriginalName("MATCH_MODE_PVP_TEAM")] PvpTeam = 7,
    /// <summary>
    /// 轮换娱乐场·物法易势 5V5：每侧 5 人、10 人公平团战，使用 6 套免费预设，不计正式评分。
    /// </summary>
    [pbr::OriginalName("MATCH_MODE_POLARITY_5V5")] Polarity5V5 = 8,
    /// <summary>
    /// 帮会全天帮战 V2·真人直打(docs/design/guild-play-v2.md):无匹配池,本人真实养成,公开观战,录回放,胜15/合格负平10。
    /// </summary>
    [pbr::OriginalName("MATCH_MODE_GUILD_WAR_PVP")] GuildWarPvp = 9,
    /// <summary>
    /// 帮会全天帮战 V2·守旗阵踢馆/灵脉守卫(docs/design/guild-play-v2.md):无匹配池,守方 AI 快照托管,公开观战,胜10/负0。
    /// </summary>
    [pbr::OriginalName("MATCH_MODE_GUILD_WAR_SIEGE")] GuildWarSiege = 10,
    /// <summary>
    /// 全服赛季战队锦标赛《群仙问道赛》:本人真实养成、公开 L2 观战、强制录回放、不进常规 Elo 榜。
    /// </summary>
    [pbr::OriginalName("MATCH_MODE_SEASON_TOURNAMENT")] SeasonTournament = 11,
  }

  public enum QueueState {
    [pbr::OriginalName("QUEUE_STATE_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// Waiting for match
    /// </summary>
    [pbr::OriginalName("QUEUE_STATE_QUEUED")] Queued = 1,
    /// <summary>
    /// Match found, instance being created
    /// </summary>
    [pbr::OriginalName("QUEUE_STATE_MATCHED")] Matched = 2,
    /// <summary>
    /// Instance created, waiting for player confirm
    /// </summary>
    [pbr::OriginalName("QUEUE_STATE_READY")] Ready = 3,
    /// <summary>
    /// Players entering scene
    /// </summary>
    [pbr::OriginalName("QUEUE_STATE_ENTERING")] Entering = 4,
    /// <summary>
    /// Player is not in any queue
    /// </summary>
    [pbr::OriginalName("QUEUE_STATE_NOT_QUEUED")] NotQueued = 5,
  }

  /// <summary>
  /// 观战帧的投递方式(battle-spectate-tiered-fanout.md §15.2,D94/D95)。
  /// </summary>
  public enum eSpectateDelivery {
    /// <summary>
    /// 未进入观战(error_message 非零)
    /// </summary>
    [pbr::OriginalName("SPECTATE_DELIVERY_NONE")] SpectateDeliveryNone = 0,
    /// <summary>
    /// L0:等 NotifyBattleAssigned,凭票直连 battle,首帧 161 经直连下发
    /// </summary>
    [pbr::OriginalName("SPECTATE_DELIVERY_DIRECT")] SpectateDeliveryDirect = 1,
    /// <summary>
    /// L1 / L2:不建直连;把 spectate_ticket 原样交给 gate 的 SubscribeSpectate,
    /// </summary>
    [pbr::OriginalName("SPECTATE_DELIVERY_LOBBY")] SpectateDeliveryLobby = 2,
  }

